const CACHE='biochemistry-memory-atlas-v6';
const SHELL=['./','index.html','lesson-01.html','chapter-02.html','chapter-03.html','chapter-04.html','chapter-05.html','chapter-06.html','chapter-07.html','recall.html','practice.html','terms.html','term.html','style.css','content.css','script.js','study.js','manifest.webmanifest','icon.svg','assets/amino-acid-zwitterion.png','assets/ramachandran-map.png','assets/myoglobin-hemoglobin-curves.png','assets/bpg-oxygen-affinity.png','assets/hbs-sickle-cell.png','assets/protein-denaturation.webp','assets/protein-color-reactions.webp','assets/sds-page-mw-markers.webp','assets/isoelectric-focusing.webp','assets/two-dimensional-electrophoresis.webp','assets/base-structures.webp','assets/base-tautomerism.webp','assets/nucleoside-structures.webp','assets/nucleotide-monophosphates.webp','assets/amp-adp-atp.webp','assets/cyclic-nucleotides.webp','assets/chargaff-ratios.webp','assets/dna-abc-form-table.webp','assets/g-quadruplex.webp','assets/supercoiled-dna-em.webp','assets/rna-tertiary-elements.webp','assets/nucleosome-model.webp','data/terms.json','data/notes.json'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==location.origin)return;event.respondWith((async()=>{const cached=await caches.match(event.request);try{const response=await fetch(event.request);if(response.ok){const cache=await caches.open(CACHE);await cache.put(event.request,response.clone())}return response}catch{if(cached)return cached;if(event.request.mode==='navigate')return(await caches.match('index.html'))||new Response('<h1>暂时离线</h1><p>联网访问一次后即可离线阅读已缓存内容。</p>',{status:503,headers:{'Content-Type':'text/html; charset=utf-8'}});return new Response('',{status:503,statusText:'Offline'})}})())});
